using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 bool contentFixture;bool ContentEnabled=>!((testing||coopCheck)&&!contentFixture);
 readonly Dictionary<int,Node3D> contentRoots=new();int contentSeed=int.MinValue;double contentScan;
 ContentSiteState Field(int i)=>game.World.Changes.FieldSite(i);
 ContentRoamingEvent FieldEvent=>game.World.Changes.FieldEvent??=new();
 string FieldEnemyId(int i,int j)=>$"field-site/{i}/{j}/{game.Save.Seed}";
 static bool IsContentEnemy(string id)=>id.StartsWith("field-site/")||id.StartsWith("field-event/");
 int FieldGuardCount(int i)=>ExpeditionContentSite.All[i].Tier==1?0:ExpeditionContentSite.All[i].Tier+(ExpeditionContentSite.All[i].Mode=="night"?1:0);
 bool FieldCleared(int i)=>Enumerable.Range(0,FieldGuardCount(i)).All(j=>(Field(i).DeadGuards&(1<<j))!=0);
 bool FieldReady(int i){var d=ExpeditionContentSite.All[i];var s=Field(i);return FieldCleared(i)&&(d.Mode!="night"||game.Night)&&(d.Mode!="generator"||s.Repaired)&&(d.Mode!="repair"||s.Repaired);}
 void ContentEnemyDeath(Infected e){if(e.Id.StartsWith("field-site/")){var bits=e.Id.Split('/');if(bits.Length==4&&int.TryParse(bits[1],out int i)&&i>=0&&i<ExpeditionContentSite.All.Length&&int.TryParse(bits[2],out int j))Field(i).DeadGuards|=1<<j;}else if(e.Id.StartsWith("field-event/")){var bits=e.Id.Split('/');if(bits.Length==5&&int.TryParse(bits[1],out int serial)&&serial==FieldEvent.Serial&&int.TryParse(bits[3],out int j))FieldEvent.Dead|=1<<j;}}
 void SpawnContentAtlas(){if(!ContentEnabled||dungeon!=null)return;if(contentSeed!=game.Save.Seed){foreach(var n in contentRoots.Values)if(GodotObject.IsInstanceValid(n))n.QueueFree();contentRoots.Clear();props.RemoveAll(p=>p.Kind==36);contentSeed=game.Save.Seed;}
  foreach(var pair in contentRoots.ToArray()){if(!GodotObject.IsInstanceValid(pair.Value)||!pair.Value.IsInsideTree()){contentRoots.Remove(pair.Key);props.RemoveAll(p=>p.Kind==36&&p.Material==pair.Key);continue;}var at=ExpeditionContentSite.Place(game.World,pair.Key);if(NearActiveSurface(Ground(at.X,at.Z),230))continue;if(GodotObject.IsInstanceValid(pair.Value)){pair.Value.GetParent()?.RemoveChild(pair.Value);pair.Value.QueueFree();}props.RemoveAll(p=>p.Kind==36&&p.Material==pair.Key);contentRoots.Remove(pair.Key);}
  for(int i=0;i<ExpeditionContentSite.All.Length;i++){var at=ExpeditionContentSite.Place(game.World,i);if(!NearActiveSurface(Ground(at.X,at.Z),180)||contentRoots.ContainsKey(i))continue;var d=ExpeditionContentSite.All[i];double floor=LetterFloor(at.X,at.Z,9,7);var root=new Node3D{Name="FieldSite_"+i,Position=new((float)at.X,(float)floor,(float)at.Z)};worldRoot.AddChild(root);contentRoots[i]=root;DressContentSite(root,i);DressFieldLocker(root,i);foreach(var child in root.FindChildren("*","GeometryInstance3D",true,false))if(child is GeometryInstance3D mesh){mesh.VisibilityRangeEnd=220;mesh.VisibilityRangeEndMargin=15;}props.Add(new(){Id=$"field-site/{game.Save.Seed}/{i}",Kind=36,Material=i,Tier=d.Tier,Position=root.ToGlobal(new(0,.3f,5.5f)),Node=root});}
  if(!CoopClient)SpawnFieldGuardians();SpawnFieldEvent();DrawWorldWorks();
 }
 void SpawnFieldGuardians(){for(int i=0;i<ExpeditionContentSite.All.Length;i++){var d=ExpeditionContentSite.All[i];if(d.Tier==1||d.Mode=="night"&&!game.Night)continue;var p=ExpeditionContentSite.Place(game.World,i);if(!NearActiveSurface(Ground(p.X,p.Z),85))continue;for(int j=0;j<FieldGuardCount(i)&&infected.Count<(CoopHost?CoopMaxEnemies:85);j++){if((Field(i).DeadGuards&(1<<j))!=0)continue;double a=j*2.1,dx=Math.Sin(a)*12;if(Math.Abs(dx)<3)dx=6+j*.5;var at=Ground(p.X+dx,p.Z+Math.Cos(a)*12);AddEnemy(FieldEnemyId(i,j),at.X,at.Z,d.Tier,d.Mode=="night"?j==0&&d.Tier>=3?2:1:0);}}}
 void TickContentAtlas(double dt){if(!ContentEnabled||CoopClient||dungeon!=null)return;contentScan-=dt;if(contentScan<=0){contentScan=1;SpawnContentAtlas();for(int i=0;i<ExpeditionContentSite.All.Length;i++){var p=ExpeditionContentSite.Place(game.World,i);var s=Field(i);if(!s.Seen&&MillPlayers().Any(a=>ExpeditionGame.Distance(a.Body.Position.X,a.Body.Position.Z,p.X,p.Z)<50))s.Seen=true;}}
  foreach(var s in game.World.Changes.FieldSites.Where(s=>s.PowerLeft>0).ToArray()){var p=ExpeditionContentSite.Place(game.World,s.Index);if(NearActiveSurface(Ground(p.X,p.Z),120)){s.PowerLeft=Math.Max(0,s.PowerLeft-dt);s.NoiseAt-=dt;if(s.NoiseAt<=0){s.NoiseAt=8;HearNoise(Ground(p.X,p.Z),65);}if(s.PowerLeft==0){s.Repaired=true;s.Outcome="The generator held. The supply cabinet is ready.";game.Persist();FeverSync();}}}
  TickFieldLockers(dt);TickFieldEvent(dt);TickWorldWorks(dt);
 }
 WorldProp NearFieldSite()=>!ContentEnabled||dungeon!=null?null:props.Where(p=>p.Kind==36&&Distance(p.Position,player.Position)<3.5f).OrderBy(p=>Distance(p.Position,player.Position)).FirstOrDefault();
 string ContentPrompt()=>NearContentVault()?"F / COURIER SEAL CACHE / SIX FIELD RECORDS":NearFieldSite() is WorldProp p?"F / "+ExpeditionContentSite.All[p.Material].Name.ToUpperInvariant():NearFieldEvent()?"F / "+FieldEventName():"";
 bool ContentInteract(){if(NearContentVault()){if(!CoopRequest("content","vault:claim"))ContentAction("vault:claim");return true;}if(NearFieldSite() is WorldProp p){if(!CoopRequest("content","open:"+p.Material))ContentAction("open:"+p.Material);return true;}if(NearFieldEvent()){if(!CoopRequest("content","event:open"))ContentAction("event:open");return true;}return false;}
 void ContentAction(string data){if(CoopClient||!ContentEnabled||data.Length>120)return;var parts=data.Split(':');if(parts.Length<2)return;if(parts[0]=="event"){FieldEventAction(parts[1]);return;}if(parts[0]=="job"){if(parts.Length==3&&int.TryParse(parts[1],out int job))FieldJobAction(job,parts[2]);return;}if(parts[0]=="vault"){ContentVaultAction();return;}if(parts[0]=="atlas"){ClaimFieldAtlas();return;}if(!int.TryParse(parts[1],out int i)||i<0||i>=ExpeditionContentSite.All.Length)return;var prop=NearFieldSite();if(prop==null||prop.Material!=i)return;var d=ExpeditionContentSite.All[i];var s=Field(i);string op=parts[0];
  if(op=="works-open"){WorkAction("open:"+i);return;}
  if(op is "locker-quiet" or "locker-force"){FieldLockerAction(i,op=="locker-force");return;}
  if(op=="open"){s.Seen=s.Read=true;if(!game.Profile.Journal.Seen.Contains("field/"+i))game.Profile.Journal.Seen.Add("field/"+i);game.Persist();if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopFieldPage),i);else ShowFieldSite(i);return;}
  if(op=="power"){if(d.Mode!="generator"||s.Repaired||s.PowerLeft>0)return;if(game.Craft.Fuel<2){game.Notice="Needs two fuel. The 60-second generator run attracts infected.";return;}game.Craft.Fuel-=2;s.PowerLeft=60;s.NoiseAt=0;s.Outcome="Generator running / remain nearby for 60 active seconds. Its noise draws infected.";}
  else if(op=="repair"){if(d.Mode!="repair"||s.Repaired||!FieldCleared(i))return;int material=d.Tier==1?0:4,cost=d.Tier==1?6:6;if(game.Craft.Materials[material]<cost){game.Notice="Needs 6 "+ExpeditionGame.ResourceNames[material];return;}game.Craft.Materials[material]-=cost;s.Repaired=true;s.Outcome="The station works again. The sealed supply compartment is accessible.";}
  else if(op is "recover" or "strip"){if(s.Recovered||s.Stripped||s.Delivered){game.Notice="This cache has already been claimed.";return;}if(!FieldReady(i)){game.Notice=d.Mode=="night"&&!game.Night?"The night receiver is locked until nightfall.":"Clear the guards and restore this site's equipment first.";return;}if(op=="recover"&&d.Town>=0){s.Recovered=true;s.Outcome="The sealed case is reserved for "+ExpeditionGame.SettlementNames[d.Town]+". Bring news to the requester to hand it over.";}else{s.Stripped=true;FieldLoot(i,d.Town>=0?2:1);s.Outcome=d.Town>=0?"You broke the seal and kept the supplies. The settlement's request cannot be completed.":"Useful supplies recovered. The record of this place stays in your field guide.";if(d.Town>=0){Town(d.Town).Trust-=4;RememberTown(d.Town,-8,s.Outcome);}}game.JourneyLoot(i);game.Career.Gain(25+d.Tier*8);}
  else if(op=="rest"){if(d.Mode!="rest"||!FieldCleared(i)||game.World.Changes.Time<s.RestAt)return;if((dogPackSource??infected).Any(e=>!Peaceful(e.Id)&&Distance(e.Body.Position,prop.Position)<20)){game.Notice="It is not safe to rest while threats are this close.";return;}if(game.Craft.Materials[0]<4){game.Notice="Needs four timber for a small fire.";return;}game.Craft.Materials[0]-=4;s.RestAt=game.World.Changes.Time+600;s.Secured=true;game.Life.Energy=Math.Min(100,game.Life.Energy+20);game.Life.Comfort=300;game.Life.Morale=Math.Min(100,game.Life.Morale+5);s.Outcome="A small fire, a hot drink and time to breathe. No instant health restoration.";}
  else return;game.Notice=s.Outcome;game.Persist();FeverSync();
 }
 void FieldLoot(int i,int scale){game.JourneyLoot(i);var d=ExpeditionContentSite.All[i];game.Life.Food+=scale;game.Life.Bandages+=d.Theme==2?2*scale:scale;game.Craft.Materials[d.Tier==1?i%3:Math.Min(6,d.Tier+1)]+=2*scale;if(d.Tier==1){game.Craft.Arrows+=4;return;}if(d.Mode=="night")game.Life.NightEssence+=2*scale;if(d.Theme==3)game.Craft.Fuel+=3*scale;if(d.Theme==4)game.Craft.Water+=3*scale;if(d.Theme==8){game.Profile.Items.Add(new ExpeditionRelic{Id=$"field/{game.Save.Seed}/{i}",Name=d.Name+" field gloves",Origin=d.Name,Slot="hands",Level=d.Tier,Armor=d.Tier*2,Vitality=d.Tier});}else if(d.Tier>=3)game.Craft.GiveAmmo(d.Tier==4?1:2,12*scale);else game.Craft.Arrows+=8;}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFieldPage(int i){if(CoopClient&&i>=0&&i<ExpeditionContentSite.All.Length)ShowFieldSite(i);}
 void FieldJobAction(int i,string op){if(i<0||i>=ExpeditionContentSite.All.Length)return;var d=ExpeditionContentSite.All[i];if(d.Town<0)return;var p=NearLiving();if(p==null||p.Kind!=32||p.Material!=d.Town)return;var t=Town(d.Town);var s=Field(i);if(t.Fallen||t.Trust<0||Standing("town/"+d.Town).Value<0||(t.DeadResidents&(1<<d.Giver))!=0){game.Notice="The requester is unavailable or does not trust you.";return;}if(op=="accept"&&!s.Accepted&&!s.Delivered&&!s.Stripped){s.Accepted=true;s.Seen=true;game.Notice=d.Request;}
  else if(op=="return"&&s.Accepted&&s.Recovered&&!s.Delivered&&!s.Stripped){s.Delivered=true;t.Food+=4;t.Water+=4;t.Trust+=4;RememberTown(d.Town,6,"You brought back the case from "+d.Name+".");game.World.Changes.Remember(CommunityOwner,$"resident/{d.Town}/{d.Giver}",4,"You completed my request: "+d.Name);game.Craft.Materials[d.Tier>=4?5:4]+=3;game.Life.Bandages+=2;game.Career.Gain(80);game.AwardResearch("field-job/"+i,2);game.WorldDecision("field/job/"+i,d.Name+" / supplies delivered to "+ResidentNames[d.Town][d.Giver]);game.Notice="Field request complete / community supplies, personal pay and reputation improved.";}else{game.Notice="This request is incomplete, already resolved, or its cache was stripped.";return;}game.Persist();FeverSync();
 }
 void ClaimFieldAtlas(){int count=game.World.Changes.FieldSites.Count(s=>s.Read);bool any=false;foreach(int goal in new[]{6,14,28}){string key=$"field-atlas/{game.Save.Seed}/{goal}";if(count<goal||game.Profile.Claimed.Contains(key))continue;game.Profile.Claimed.Add(key);game.Career.Gain(goal*5);if(goal==6){game.Life.Bandages+=3;game.Life.Food+=3;}else game.Profile.Items.Add(new ExpeditionRelic{Id=key,Name=goal==14?"South Bank courier coat":"Ashen cartographer hood",Origin="The Names We Keep / field atlas",Slot=goal==14?"chest":"head",Level=goal==14?3:4,Armor=goal==14?25:12,Vitality=8});any=true;}game.Notice=any?"Field atlas milestone claimed / saved to this character":"No unclaimed field atlas milestone.";game.Persist();}
}
